package thaumichorizons;

import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.*;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.world.*;
import net.minecraft.world.entity.*;
import net.minecraft.world.entity.ai.attributes.Attributes;
import net.minecraft.world.item.*;
import net.minecraft.world.item.component.CustomData;
import net.minecraft.world.level.*;
import net.minecraft.world.level.block.Blocks;
import net.neoforged.neoforge.gametest.*;
import thaumcraft.aspect.*;
import thaumcraft.research.*;

@GameTestHolder(ThaumicHorizons.ID)
@PrefixGameTestTemplate(false)
public final class VatGameTests {
    static VatEntity vat(GameTestHelper h){return Vats.form(h.getLevel(),h.absolutePos(new BlockPos(1,2,1)));}
    static void tick(VatEntity v,int n){for(int i=0;i<n;i++)VatEntity.tick(v.getLevel(),v.getBlockPos(),v.getBlockState(),v);}
    static ItemStack sample(LivingEntity e){ItemStack sample=new ItemStack(Content.item("blood_sample"));CompoundTag tag=new CompoundTag();tag.put("critter",Vats.genetics(e));sample.set(DataComponents.CUSTOM_DATA,CustomData.of(tag));return sample;}
    static void pedestals(VatEntity v,VatRecipes.Recipe recipe){int[][] offsets={{-2,-1,0},{2,-1,0},{0,-1,-2},{0,-1,2},{-2,-1,-2},{2,-1,2},{-2,-1,2},{2,-1,-2}};for(int i=0;i<recipe.ingredients().size();i++){var off=offsets[i];var p=v.getBlockPos().offset(off[0],off[1],off[2]);v.getLevel().setBlockAndUpdate(p,thaumcraft.registry.ModBlocks.ARCANE_PEDESTAL.get().defaultBlockState());var ped=(thaumcraft.infusion.PedestalBlockEntity)v.getLevel().getBlockEntity(p);ped.setStackFromInfusion(recipe.ingredients().get(i).displayStacks().getFirst().copy());}}
    @GameTest(template="test/platform") public static void vatFormationAndDismantling(GameTestHelper h){
        BlockPos origin=h.absolutePos(new BlockPos(1,2,1));for(BlockPos off:BlockPos.betweenClosed(0,0,0,2,3,2))h.getLevel().setBlockAndUpdate(origin.offset(off),Vats.raw(off.getX(),off.getY(),off.getZ()));
        h.assertTrue(Vats.fits(h.getLevel(),origin),"valid source-water blueprint rejected");var be=Vats.form(h.getLevel(),origin);h.assertTrue(be.intact(),"formed vat incomplete");
        for(Direction d:Direction.Plane.HORIZONTAL){var part=(VatEntity)h.getLevel().getBlockEntity(be.getBlockPos().below(3).relative(d));h.assertValueEqual(part.part(),4,"bottom cardinal connector");h.assertTrue(part.master()==be,"connector cannot resolve master");}
        BlockPos broken=origin.offset(0,1,0);h.getLevel().destroyBlock(broken,false);h.assertTrue(h.getLevel().getBlockState(be.getBlockPos()).is(thaumcraft.registry.ModBlocks.ALCHEMICAL_CONSTRUCT.get()),"lid not restored");h.assertTrue(h.getLevel().getBlockState(origin).is(thaumcraft.registry.ModBlocks.GREATWOOD_PLANKS.get()),"base not restored");h.succeed();
    }
    @GameTest(template="test/platform") public static void flowingWaterCannotFormVat(GameTestHelper h){BlockPos origin=h.absolutePos(new BlockPos(1,2,1));for(BlockPos off:BlockPos.betweenClosed(0,0,0,2,3,2))h.getLevel().setBlockAndUpdate(origin.offset(off),Vats.raw(off.getX(),off.getY(),off.getZ()));h.getLevel().setBlockAndUpdate(origin.offset(1,1,1),Blocks.WATER.defaultBlockState().setValue(net.minecraft.world.level.block.LiquidBlock.LEVEL,3));h.assertTrue(!Vats.fits(h.getLevel(),origin),"flowing water accepted");h.succeed();}
    @GameTest(template="test/platform") public static void formationRequiresResearchAndPaysDiscountedVisAtomically(GameTestHelper h){
        var level=h.getLevel();BlockPos origin=h.absolutePos(new BlockPos(1,2,1));for(BlockPos off:BlockPos.betweenClosed(0,0,0,2,3,2))level.setBlockAndUpdate(origin.offset(off),Vats.raw(off.getX(),off.getY(),off.getZ()));var player=h.makeMockPlayer(GameType.SURVIVAL);var stack=thaumcraft.wand.Wands.create(thaumcraft.wand.WandRegistry.CAP_GOLD,thaumcraft.wand.WandRegistry.ROD_GREATWOOD,false);thaumcraft.wand.Wands.fill(stack);var wand=(thaumcraft.wand.WandItem)stack.getItem();BlockPos clicked=origin.offset(0,1,0);
        h.assertTrue(!Vats.tryForm(level,stack,player,clicked,Direction.UP),"vat formed without research");Knowledge.get(player).addResearch("healingVat");thaumcraft.wand.Wands.storeVis(stack,Aspect.WATER,0);int earth=thaumcraft.wand.Wands.getVis(stack,Aspect.EARTH);h.assertTrue(!Vats.tryForm(level,stack,player,clicked,Direction.UP),"vat formed without enough water vis");h.assertValueEqual(thaumcraft.wand.Wands.getVis(stack,Aspect.EARTH),earth,"failed formation consumed partial vis");h.assertTrue(Vats.fits(level,origin),"failed formation changed the blueprint");thaumcraft.wand.Wands.fill(stack);int before=thaumcraft.wand.Wands.getVis(stack,Aspect.WATER),cost=(int)(5000*wand.getConsumptionModifier(stack,player,Aspect.WATER,true));h.assertTrue(Vats.tryForm(level,stack,player,clicked,Direction.UP),"valid wand activation failed");h.assertValueEqual(thaumcraft.wand.Wands.getVis(stack,Aspect.WATER),before-cost,"wand discount or formation cost incorrect");h.assertTrue(level.getBlockEntity(origin.offset(1,3,1)) instanceof VatEntity,"controller missing after activation");h.succeed();
    }
    @GameTest(template="test/platform") public static void creatureInfusionIngredientsAndPotions(GameTestHelper h){
        h.assertValueEqual(VatRecipes.all().size(),40,"20 species plus 10 general plus 10 self recipes");for(var recipe:VatRecipes.all()){h.assertTrue(ResearchCategories.getResearch(recipe.research())!=null,"unknown research "+recipe.key());for(var i:recipe.ingredients())h.assertTrue(i.exists(),"unresolved ingredient "+recipe.key()+" "+i);}
        var recipe=VatRecipes.get("creature_1");var items=new ArrayList<>(recipe.ingredients().stream().map(i->i.displayStacks().getFirst()).toList());Collections.reverse(items);h.assertTrue(VatRecipes.matches(recipe.ingredients(),items),"order-dependent pedestal matching");items.set(2,new ItemStack(Items.POTION));h.assertTrue(!VatRecipes.matches(recipe.ingredients(),items),"water bottle substitutes for strong swiftness");h.succeed();
    }
    @GameTest(template="test/platform") public static void vatHealsAndPaysForHunger(GameTestHelper h){var v=vat(h);var p=h.makeMockPlayer(GameType.SURVIVAL);v.subject=p;p.setHealth(4);v.stored.add(Aspect.HEAL,1);tick(v,1);h.assertValueEqual((int)p.getHealth(),12,"healing potency");h.assertValueEqual(v.stored.getAmount(Aspect.HEAL),0,"free healing");h.assertValueEqual(v.progress,39,"healing cooldown");p.setHealth(p.getMaxHealth());v.progress=0;p.getFoodData().setFoodLevel(5);v.stored.add(Aspect.HUNGER,1);tick(v,1);h.assertValueEqual(p.getFoodData().getFoodLevel(),9,"hunger potency");h.assertValueEqual(v.stored.getAmount(Aspect.HUNGER),0,"hunger essentia not consumed");h.succeed();}
    @GameTest(template="test/platform") public static void cloneRequiresAllInheritedEssentia(GameTestHelper h){
        var v=vat(h);var cow=EntityType.COW.create(h.getLevel());Infusions.add(cow,4,null,new AspectList().add(Aspect.ARMOR,16));v.inventory.setStackInSlot(0,sample(cow));v.inventory.setStackInSlot(1,new ItemStack(Content.item("nutrients"),2));tick(v,1);h.assertValueEqual(v.mode,1,"clone not started");v.progress=0;v.stored.add(Aspect.LIFE,4);tick(v,1);h.assertTrue(v.subject==null,"inherited infusion cost bypassed");v.stored.add(Aspect.ARMOR,16);tick(v,1);h.assertTrue(v.subject!=null&&Infusions.has(v.subject,4),"infusion not inherited");h.assertTrue(!v.subject.getUUID().equals(cow.getUUID()),"clone reused donor UUID");h.assertValueEqual(v.progress,799,"clone growth duration");h.assertValueEqual(v.inventory.getStackInSlot(1).getCount(),1,"nutrient consumption");tick(v,800);h.assertValueEqual(v.mode,0,"clone never matured");h.succeed();
    }
    @GameTest(template="test/platform") public static void geneticsStripEquipmentAndOwnership(GameTestHelper h){
        var wolf=EntityType.WOLF.create(h.getLevel());wolf.setOwnerUUID(UUID.randomUUID());wolf.setTame(true,false);wolf.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack(Items.DIAMOND,64));wolf.setItemSlot(EquipmentSlot.BODY,new ItemStack(Items.WOLF_ARMOR));Infusions.add(wolf,7,wolf.getOwnerUUID(),new AspectList().add(Aspect.MIND,4));var clone=Vats.cloneFrom(sample(wolf),h.getLevel());h.assertTrue(clone!=null&&clone.getMainHandItem().isEmpty()&&clone.getItemBySlot(EquipmentSlot.BODY).isEmpty(),"clone duplicated equipment");h.assertTrue(clone instanceof TamableAnimal tame&&!tame.isTame()&&tame.getOwnerUUID()==null,"clone retained vanilla owner");h.succeed();
    }
    @GameTest(template="test/platform") public static void specimenRoundTripPreservesIdentity(GameTestHelper h){var cow=EntityType.COW.create(h.getLevel());cow.setHealth(5);Infusions.add(cow,3,null,new AspectList().add(Aspect.HEAL,8));var loaded=Specimens.read(Specimens.write(cow),h.getLevel());h.assertTrue(loaded!=null&&loaded.getUUID().equals(cow.getUUID()),"transport changed identity");h.assertTrue(Infusions.has(loaded,3),"transport lost infusion attachment");h.assertValueEqual((int)loaded.getHealth(),5,"transport changed health");h.succeed();}
    @GameTest(template="test/platform") public static void shellGrowthConsumesExactEssentia(GameTestHelper h){var v=vat(h);v.inventory.setStackInSlot(0,new ItemStack(Content.item("corpse_effigy")));tick(v,1);h.assertValueEqual(v.mode,3,"effigy not growing");v.progress=0;v.stored.add(Aspect.LIFE,8).add(Aspect.HEAL,7);tick(v,1);h.assertValueEqual(v.mode,3,"effigy grew without all heal essentia");v.stored.add(Aspect.HEAL,1);tick(v,1);h.assertValueEqual(v.mode,4,"effigy not ready");h.assertTrue(v.inventory.getStackInSlot(0).isEmpty()&&v.stored.isEmpty(),"effigy or essentia not consumed");h.succeed();}
    @GameTest(template="test/platform") public static void vatPersistenceMidRitual(GameTestHelper h){var v=vat(h);v.subject=EntityType.COW.create(h.getLevel());v.mode=2;v.recipeKey="creature_4";v.operator=UUID.randomUUID();v.remaining.add(2);v.demand.add(Aspect.CRYSTAL,11);v.cycles=93;v.itemCount=3;v.suckingFrom=v.getBlockPos().below(3);var nbt=v.saveWithFullMetadata(h.getLevel().registryAccess());var restored=new VatEntity(v.getBlockPos(),v.getBlockState());restored.loadWithComponents(nbt,h.getLevel().registryAccess());restored.setLevel(h.getLevel());h.assertTrue(restored.occupant()!=null,"stored subject lost");h.assertTrue(restored.occupant().getUUID().equals(v.subject.getUUID()),"subject identity changed on load");h.assertValueEqual(restored.demand.getAmount(Aspect.CRYSTAL),11,"remaining cost changed");h.assertValueEqual(restored.itemCount,3,"item windup lost");h.assertTrue(restored.remaining.equals(List.of(2))&&restored.recipeKey.equals("creature_4")&&restored.operator.equals(v.operator),"ritual state lost");h.succeed();}
    @GameTest(template="test/platform") public static void infusionAttributesDoNotStackOnReload(GameTestHelper h){var wolf=EntityType.WOLF.create(h.getLevel());double speed=wolf.getAttributeValue(Attributes.MOVEMENT_SPEED),attack=wolf.getAttributeValue(Attributes.ATTACK_DAMAGE);Infusions.add(wolf,1,null,new AspectList());Infusions.add(wolf,2,null,new AspectList());for(int i=0;i<100;i++)Infusions.apply(wolf);h.assertTrue(Math.abs(wolf.getAttributeValue(Attributes.MOVEMENT_SPEED)-speed*1.3)<.00001,"speed stacks");h.assertTrue(Math.abs(wolf.getAttributeValue(Attributes.ATTACK_DAMAGE)-attack*3)<.00001,"claws stack");h.assertTrue(!Infusions.add(wolf,2,null,new AspectList()),"duplicate infusion accepted");h.succeed();}
    @GameTest(template="test/platform") public static void selfInfusionsRequireGrownBody(GameTestHelper h){var player=h.makeMockPlayer(GameType.SURVIVAL);Knowledge.get(player).addResearch("selfInfusion");var cow=EntityType.COW.create(h.getLevel());var recipe=VatRecipes.get("self_1");var items=recipe.ingredients().stream().map(i->i.displayStacks().getFirst()).toList();h.assertTrue(VatRecipes.find(items,false,cow,player,new int[12])==null,"self infusion accepted living creature");h.assertTrue(VatRecipes.find(items,true,null,player,new int[12])==recipe,"shell recipe not found");h.assertTrue(VatRecipes.find(items,true,null,player,new int[]{1})==null,"duplicate shell infusion accepted");h.succeed();}
    @GameTest(template="test/platform") public static void failedInfusionClearsSubjectAndWork(GameTestHelper h){var v=vat(h);v.subject=EntityType.COW.create(h.getLevel());v.mode=2;v.recipeKey="creature_4";v.remaining.add(0);v.demand.add(Aspect.ARMOR,15);v.shellInfusions[0]=4;v.failInfusion();h.assertTrue(v.mode==0&&v.subject==null&&v.recipeKey.isEmpty()&&v.demand.isEmpty()&&v.remaining.isEmpty()&&v.shellInfusions[0]==0,"failed ritual retained a body or unpaid work");h.succeed();}
    @GameTest(template="test/platform") public static void completeCreatureRitualSurvivesReload(GameTestHelper h){
        var v=vat(h);v.subject=EntityType.COW.create(h.getLevel());var recipe=VatRecipes.get("creature_2");pedestals(v,recipe);h.getLevel().setBlockAndUpdate(v.getBlockPos().above(),Vats.MATRIX.get().defaultBlockState());var player=h.makeMockPlayer(GameType.SURVIVAL);Knowledge.get(player).addResearch("infusionVat");
        h.assertTrue(v.startInfusion(player),"valid pedestal ritual refused");v.instability=0;while(v.needed()!=null)v.receive(v.needed(),1000);for(int i=0;i<7;i++)v.infusionCycle();h.assertValueEqual(v.remaining.size(),1,"first ingredient not consumed after windup");
        var restored=new VatEntity(v.getBlockPos(),v.getBlockState());restored.loadWithComponents(v.saveWithFullMetadata(h.getLevel().registryAccess()),h.getLevel().registryAccess());restored.setLevel(h.getLevel());h.getLevel().setBlockEntity(restored);restored.onLoad();
        for(int i=0;i<50&&restored.mode==2;i++)restored.infusionCycle();h.assertTrue(restored.mode==0&&Infusions.has(restored.occupant(),2),"ritual did not finish after reload");for(var p:restored.pedestals)h.assertTrue(((thaumcraft.infusion.PedestalBlockEntity)h.getLevel().getBlockEntity(p)).getStack().isEmpty(),"ingredient survived completed ritual");h.succeed();
    }
    @GameTest(template="test/platform") public static void completeSelfRitualRetainsOtherInfusions(GameTestHelper h){
        var v=vat(h);v.mode=4;v.shellInfusions[0]=3;var recipe=VatRecipes.get("self_5");pedestals(v,recipe);h.getLevel().setBlockAndUpdate(v.getBlockPos().above(),Vats.MATRIX.get().defaultBlockState());var player=h.makeMockPlayer(GameType.SURVIVAL);Knowledge.get(player).addResearch("silverHeart");h.assertTrue(v.startInfusion(player),"self ritual refused");v.instability=0;while(v.needed()!=null)v.receive(v.needed(),1000);for(int i=0;i<80&&v.mode==2;i++)v.infusionCycle();h.assertTrue(v.mode==4&&v.shellInfusions[0]==3&&v.shellInfusions[1]==5,"self ritual erased an existing infusion or did not complete");h.succeed();
    }
    @GameTest(template="test/platform") public static void runicHideHasSixPointSharedBudget(GameTestHelper h){var cow=EntityType.COW.create(h.getLevel());Infusions.add(cow,8,null,new AspectList());float health=cow.getHealth();cow.hurt(cow.damageSources().magic(),4);h.assertValueEqual((int)cow.getHealth(),(int)health,"runic hide did not absorb hit");h.assertValueEqual(Infusions.DATA.get(cow).getInt("runic"),2,"incorrect shield charge");cow.invulnerableTime=0;cow.hurt(cow.damageSources().magic(),4);h.assertValueEqual((int)cow.getHealth(),(int)health-2,"shield generated extra protection");h.assertValueEqual(Infusions.DATA.get(cow).getInt("runic"),0,"shield charge below zero");h.succeed();}
    @GameTest(template="test/platform") public static void fangsPoisonVictimAndNeverAttacker(GameTestHelper h){var wolf=EntityType.WOLF.create(h.getLevel());var cow=EntityType.COW.create(h.getLevel());Infusions.add(wolf,9,null,new AspectList());cow.hurt(cow.damageSources().mobAttack(wolf),2);h.assertTrue(cow.hasEffect(net.minecraft.world.effect.MobEffects.POISON)&&!wolf.hasEffect(net.minecraft.world.effect.MobEffects.POISON),"eldritch fangs poison wrong entity");h.succeed();}
    @GameTest(template="test/platform") public static void warpedTumorHoldsFiftyAndReturnsAllWarp(GameTestHelper h){
        var profile=new com.mojang.authlib.GameProfile(UUID.randomUUID(),"THWarpTest");var player=net.neoforged.neoforge.common.util.FakePlayerFactory.get(h.getLevel(),profile);
        Warp.set(player,20,WarpType.PERMANENT);Warp.set(player,25,WarpType.STICKY);Warp.set(player,30,WarpType.TEMPORARY);Infusions.add(player,8,null,new AspectList());Infusions.absorbWarp(player);var tag=Infusions.DATA.get(player);
        h.assertValueEqual(tag.getInt("tumorPermanent"),20,"permanent warp priority");h.assertValueEqual(tag.getInt("tumorSticky"),25,"sticky warp priority");h.assertValueEqual(tag.getInt("tumorTemporary"),5,"tumor capacity");h.assertValueEqual(Warp.total(player),25,"wrong remaining warp");Infusions.returnWarp(player);h.assertValueEqual(Warp.get(player,WarpType.PERMANENT),20,"permanent warp lost");h.assertValueEqual(Warp.get(player,WarpType.STICKY),25,"sticky warp lost");h.assertValueEqual(Warp.get(player,WarpType.TEMPORARY),30,"temporary warp lost");Infusions.returnWarp(player);h.assertValueEqual(Warp.total(player),75,"warp restored twice");h.succeed();
    }
    @GameTest(template="test/platform") public static void filledEssentiaJarCannotCaptureCreature(GameTestHelper h){var player=h.makeMockPlayer(GameType.SURVIVAL);var stack=new ItemStack(thaumcraft.registry.ModBlocks.WARDED_JAR.get());AspectKeys.ASPECTS.set(stack,new AspectList().add(Aspect.LIFE,64));player.getInventory().setItem(0,stack);h.assertValueEqual(Specimens.emptyJar(player),-1,"filled essentia jar was treated as empty");h.succeed();}
    @GameTest(template="test/platform") public static void specimenJarBreakDropsOneSavedCreature(GameTestHelper h){var pos=new BlockPos(3,2,3);h.setBlock(pos,Specimens.JAR.get());SpecimenJarEntity jar=h.getBlockEntity(pos);var cow=EntityType.COW.create(h.getLevel());jar.stack=Specimens.write(cow);var nbt=jar.saveWithFullMetadata(h.getLevel().registryAccess());var restored=new SpecimenJarEntity(jar.getBlockPos(),jar.getBlockState());restored.loadWithComponents(nbt,h.getLevel().registryAccess());restored.setLevel(h.getLevel());h.assertTrue(restored.occupant()!=null&&restored.occupant().getUUID().equals(cow.getUUID()),"placed specimen lost identity on save");h.getLevel().destroyBlock(jar.getBlockPos(),true);var drops=h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new net.minecraft.world.phys.AABB(jar.getBlockPos()).inflate(1),e->e.getItem().is(Content.item("specimen_jar")));h.assertValueEqual(drops.size(),1,"jar duplicated or lost its contents when broken");h.succeed();}
    @GameTest(template="test/platform") public static void loyaltyGivesPassiveAnimalThreeBaseDamage(GameTestHelper h){var cow=EntityType.COW.create(h.getLevel());var wolf=EntityType.WOLF.create(h.getLevel());cow.setPos(h.absolutePos(new BlockPos(2,2,2)).getCenter());wolf.setPos(cow.position());Infusions.add(cow,7,UUID.randomUUID(),new AspectList());cow.setLastHurtByMob(wolf);cow.tickCount=20;float before=wolf.getHealth();cow.goalSelector.tick();h.assertValueEqual((int)wolf.getHealth(),(int)before-3,"passive loyal animal cannot retaliate or uses wrong base damage");h.succeed();}
}
